os.makedirs('versoes', exist_ok=True)
def data(p):
    if not p: return ''
    a = subprocess.run(['git', '-C', R, 'log', '--format=%as', '--', p], capture_output=True, text=True).stdout.split()
    return a[-1] if a else ''
for v in V:
    v['data'] = data(v['pasta']) or ('2026-11-12' if v['id'] == 'p2' else '')
    src = v.pop('img')
    if src:
        im = Image.open(os.path.join(R, src)).convert('RGBA'); bg = Image.new('RGBA', im.size, (237, 229, 211, 255)); bg.alpha_composite(im); im = bg.convert('RGB'); im.thumbnail((900, 900))
        im.save(f'versoes/{v["id"]}.jpg', quality=78); v['imagem'] = f'versoes/{v["id"]}.jpg'; v['origem_imagem'] = src
    else: v['imagem'] = ''
json.dump(dict(gerado_de='kumo-central/gerar_versoes.py', versoes=V), open('versoes.json', 'w'), ensure_ascii=False, indent=1)
print('versoes', len(V), 'kb', sum(os.path.getsize('versoes/' + f) for f in os.listdir('versoes')) // 1024)
